from z3 import *

def solve_social_golfers(n_golfers, n_weeks, n_groups, group_size):
    # x[w][p] is the group of golfer p in week w
    x = [[Int(f"x_{w}_{p}") for p in range(n_golfers)] for w in range(n_weeks)]

    solver = Solver()

    # Each golfer is in a group 0..n_groups-1
    for w in range(n_weeks):
        for p in range(n_golfers):
            solver.add(x[w][p] >= 0, x[w][p] < n_groups)

    # Each group has exactly group_size golfers
    for w in range(n_weeks):
        for g in range(n_groups):
            solver.add(Sum([If(x[w][p] == g, 1, 0) for p in range(n_golfers)]) == group_size)

    # No pair of golfers in the same group more than once
    for p1 in range(n_golfers):
        for p2 in range(p1 + 1, n_golfers):
            # They are in the same group in week w if x[w][p1] == x[w][p2]
            solver.add(Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(n_weeks)]) <= 1)

    if solver.check() == sat:
        model = solver.model()
        result = []
        for w in range(n_weeks):
            for p in range(n_golfers):
                result.append(model.evaluate(x[w][p]).as_long())
        return result
    else:
        return None

# Parameters: 24 golfers, 8 weeks, 8 groups, 3 players per group
result = solve_social_golfers(24, 8, 8, 3)
print(result)

def verify_solution(result, n_golfers, n_weeks, n_groups, group_size):
    if result is None:
        return False

    # Check if each week has correct group sizes
    for w in range(n_weeks):
        for g in range(n_groups):
            count = 0
            for p in range(n_golfers):
                if result[w * n_golfers + p] == g:
                    count += 1
            if count != group_size:
                print(f"Week {w}, Group {g} has {count} players, expected {group_size}")
                return False

    # Check if no pair of golfers in the same group more than once
    pairs = {}
    for w in range(n_weeks):
        for g in range(n_groups):
            group_members = [p for p in range(n_golfers) if result[w * n_golfers + p] == g]
            for i in range(len(group_members)):
                for j in range(i + 1, len(group_members)):
                    p1, p2 = group_members[i], group_members[j]
                    pair = tuple(sorted((p1, p2)))
                    if pair in pairs:
                        print(f"Pair {pair} in same group in week {pairs[pair]} and week {w}")
                        return False
                    pairs[pair] = w
    return True

